(()=>{const dateFrom=value=>new Date(`${String(value).slice(0,10)}T12:00:00`);const formatDate=value=>dateFrom(value).toLocaleDateString('pt-BR',{day:'2-digit',month:'long'});const escape=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
function mount(event){const date=dateFrom(event.startDate);const href=`/inscricao.html?event=${encodeURIComponent(event.id)}`;document.body.insertAdjacentHTML('afterbegin',`<aside class="event-alert-bar" data-event-alert hidden><p><strong>Próximo encontro:</strong> ${escape(event.title)} — ${escape(formatDate(event.startDate))} <span>${escape([event.timeLabel,event.location].filter(Boolean).join(' · '))}</span></p><a href="${href}">Inscreva-se →</a></aside><dialog class="event-folder" data-event-folder aria-labelledby="event-folder-title"><div class="event-folder-card"><div class="event-folder-date"><small>Próximo encontro</small><strong>${String(date.getDate()).padStart(2,'0')}</strong><span>${escape(date.toLocaleDateString('pt-BR',{month:'long'}))}</span></div><div class="event-folder-content"><button class="event-folder-close" type="button" aria-label="Fechar">×</button><p class="event-folder-kicker">A Fonte do Empreendedor apresenta</p><h2 id="event-folder-title">${escape(event.title)}</h2><p class="event-folder-meta">${escape([formatDate(event.startDate),event.timeLabel,event.location].filter(Boolean).join(' · '))}</p><a class="event-folder-register" href="${href}"><span>Fazer minha inscrição</span><b>→</b></a><p class="event-folder-note">Vagas vinculadas ao próximo encontro da programação.</p></div></div></dialog>`);const folder=document.querySelector('[data-event-folder]');const alert=document.querySelector('[data-event-alert]');const revealAlert=()=>{alert.hidden=false;document.body.classList.add('event-alert-visible')};folder.querySelector('.event-folder-close').onclick=()=>folder.close();folder.addEventListener('click',e=>{if(e.target===folder)folder.close()});folder.addEventListener('close',revealAlert,{once:true});setTimeout(()=>{document.querySelector('dialog[open]')?revealAlert():folder.showModal()},350)}
fetch('/api/public-data').then(response=>response.ok?response.json():Promise.reject()).then(({events=[],eventPromoEnabled=true})=>{if(!eventPromoEnabled)return;const today=new Date().toISOString().slice(0,10);const next=events.filter(event=>event.endDate>=today)[0];if(next)mount(next)}).catch(()=>{});
})();
